#!/bin/sh
set -eu

crate_dir=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
repo_dir=$(CDPATH= cd -- "$crate_dir/../.." && pwd)
formal_dir="$repo_dir/formal/dclutch-semantics"
accepted="$crate_dir/src/payoff/generated_runtime_v3.rs"
temporary=$(mktemp "${TMPDIR:-/tmp}/dclutch-product-basis-runtime-v3.XXXXXX")
trap 'rm -f "$temporary"' EXIT HUP INT TERM

(
  cd "$formal_dir"
  lake build DClutchSemantics.ProductBasisV3Abi
  lake env lean --run EmitProductBasisV3AbiRust.lean > "$temporary"
)

test "$(sed -n '1p' "$temporary")" = \
  '// @generated by formal/dclutch-semantics/EmitProductBasisV3AbiRust.lean; do not edit.'

# Pinned by value, not merely by shape. Every literal below is an offset that
# deployed decoders already read on chain, so a Lean schema edit that moves one
# fails here rather than at settlement. The two reserved spans are named
# explicitly because they are what lets an old decoder refuse -- rather than
# misread -- a record written by a newer one.
grep -q '^pub const BASIS_HEADER_BYTES_V3: usize = 256;$' "$temporary"
grep -q '^pub const BASIS_SCHEMA_V3: u16 = 3;$' "$temporary"
grep -q '^pub const BASIS_KIND_OFFSET_V3: usize = 16;$' "$temporary"
grep -q '^pub const BASIS_ROUNDING_OFFSET_V3: usize = 17;$' "$temporary"
# The reserved spans, now SPENT and pinned where they were spent. Byte 18 is
# the degree, byte 19 its flags, and 208 the certificate digest; sixteen
# reserved bytes survive at 240. No offset moved -- every field a deployed
# decoder reads is where it was -- which is what makes an old decoder refuse a
# curved record rather than misread one.
grep -q '^pub const BASIS_SPLINE_DEGREE_OFFSET_V3: usize = 18;$' "$temporary"
grep -q '^pub const BASIS_SPLINE_FLAGS_OFFSET_V3: usize = 19;$' "$temporary"
grep -q '^pub const BASIS_PRICE_GATE_DIGEST_OFFSET_V3: usize = 208;$' "$temporary"
grep -q '^pub const BASIS_SPLINE_INTERIOR_MULTIPLICITY_FLAG_V3: u8 = 1;$' "$temporary"
grep -q '^pub const BASIS_WIDTH_OFFSET_V3: usize = 20;$' "$temporary"
grep -q '^pub const BASIS_HEADER_TAIL_RESERVED_OFFSET_V3: usize = 240;$' "$temporary"
grep -q '^pub const TERM_BYTES_V3: usize = 32;$' "$temporary"
grep -q '^pub const TERM_AMPLITUDE_OFFSET_V3: usize = 24;$' "$temporary"

# The three kind discriminants, pinned by value. Byte 3 is allocated and
# refused everywhere -- no decoder accepts it and no encoder emits it into a
# record -- so pinning it here is what keeps a later family from claiming a tag
# the tree already reserves. The degree interval is pinned because the Rust
# admission conjunct demands a price-gate certificate for the whole of it
# without comparing anything at runtime, and `exempt_degree_below_spline_interval`
# is the proof that is sound only while the interval starts above 1.
grep -q '^pub const BASIS_CATEGORICAL_KIND_V3: u8 = 1;$' "$temporary"
grep -q '^pub const BASIS_GRADED_COMPLEMENT_KIND_V3: u8 = 2;$' "$temporary"
grep -q '^pub const BASIS_SPLINE_DEGREE_2_TO_3_KIND_V3: u8 = 3;$' "$temporary"
grep -q '^pub const BASIS_SPLINE_MINIMUM_DEGREE_V3: u8 = 2;$' "$temporary"
grep -q '^pub const BASIS_SPLINE_MAXIMUM_DEGREE_V3: u8 = 3;$' "$temporary"

rustfmt --edition 2024 "$temporary"
cmp "$temporary" "$accepted"
